def find_rectangular_regions(grid, shape):
    """Find all maximal rectangular regions of 4s (at least 2x2)"""
    visited = set()
    regions = []

    for r in range(shape[0]):
        for c in range(shape[1]):
            if grid[r][c] == 4 and (r,c) not in visited:
                # Find maximal rectangle containing (r,c)
                # Expand right
                max_c = c
                while max_c + 1 < shape[1] and grid[r][max_c+1] == 4 and (r, max_c+1) not in visited:
                    max_c += 1
                    if max_c > c:
                        visited.add((r, max_c))

                if max_c <= c:
                    continue
                for cc in range(c, max_c+1):
                    visited.add((r, cc))

                # Expand down
                max_r = r
                while max_r + 1 < shape[0] and all(grid[max_r+1][cc] == 4 for cc in range(c, max_c+1)):
                    max_r += 1
                    for cc in range(c, max_c+1):
                        visited.add((max_r, cc))

                if max_r <= r:
                    continue

                regions.append((r, c, max_r, max_c))

    return regions

